pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Linear residual cost, but we apply a square root to 
    // prioritize tighter fits exponentially.
    let mut score = (post_residual as f64).sqrt() * 10.0;

    // Fragmentation control:
    // Penalize small unusable slivers. If residual is < 10, it's a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powi(2) * 1.5;
    }

    // Lookahead refinement:
    // If next_item_size is large, strongly penalize bins that will be too small
    // to fit the next item effectively.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward bins that remain open to accommodate the next large item
            score -= (next_item_size as f64 / bin_capacity as f64) * 5.0;
        }
    }

    // Dynamic thresholding:
    // Late-game: Force consolidation by heavily punishing new bin creation.
    // Early-game: Allow more bins to maintain flexibility.
    if is_new_bin {
        let new_bin_base_cost = 45.0 + (progress * 50.0) + (open_bins_count as f64 * 0.5);
        score = new_bin_base_cost;
    } else {
        // Reward filling bins that are currently more empty than the mean,
        // effectively balancing the load across active bins.
        if bin_residual as f64 > mean_residual {
            score -= 6.0;
        }

        // Final consolidation: If this is the only bin that fits the item,
        // make it highly attractive to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Penalize bins that drift too far from the optimal packing target (e.g. 5)
        score += ((post_residual as f64 - 5.0).abs()) * 0.3;
    }

    // Global pressure: penalize total open bins to keep the search space narrow
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for creating a "fragment" (a residual so small it's likely unusable)
    // We penalize values below 10 (the minimum item size) exponentially.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(3) * 2.0;
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current bin's post_residual is smaller than the next item, we penalize it.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive at 
    // filling bins tightly to avoid trailing fragmentation.
    // If we are late in the stream, punish large residuals more heavily.
    score += (bin_capacity as f64 - post) * progress * 0.5;

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We make it expensive to open a new bin unless existing bins are very poor fits.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is constant, but scales with 
        // the average waste in existing bins to encourage reuse.
        score = 25.0 + (mean_residual * 0.5);
    } else {
        // Reward bins that bring the mean residual closer to a target "optimal" 
        // packing density (e.g., 5-10 residual).
        let deviation = (post - 7.0).abs();
        score += deviation * 0.2;
    }

    // If this is the last fitting bin, prioritize it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

