pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core Best Fit: prioritize smallest remaining space
    let mut score = post_residual as f64;

    // Adaptive sliver avoidance: items >= 10, so any residual < 10 is effectively dead space
    if post_residual > 0 && post_residual < 10 {
        score += 65.0 - (post_residual as f64 * 2.0);
    }

    // New bin dynamic thresholding
    if is_new_bin {
        // Penalty for new bins increases as we approach the end of the stream to force consolidation
        let new_bin_penalty = 35.0 + (progress * 45.0);
        score += new_bin_penalty;

        // If existing bins can accommodate this item, discourage starting a new one
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // If this bin is the "last resort" for an item, heavily prioritize it
        if fitting_bins_count == 1 {
            score -= 75.0;
        }

        // Reward bins that stay near the running mean to prevent outliers
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.25;
    }

    // Lookahead: If next item is large (> 50), penalize bins that will be too small
    if next_item_size > 50 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward bins that can accommodate the large next item
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // For standard items, reward bins that maintain a buffer for the next item
        score -= 8.0;
    }

    // Fragmentation control: reduce score for bins that keep total open bins count balanced
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}
